exec(open('/home/claude/work/gita/gc.py').read())
DQ=lambda lab,items: S(lab,'Y',None,'DAIVĪ SAMPAT',B,''.join(T(160,44+k*min(22,118//len(items)),t,9) for k,t in enumerate(items)))
AQ=lambda lab,cap: S(lab,'',None,cap,B,DEMON(70,140,1.6,'#7a2a6a')+'<ellipse cx="160" cy="60" rx="50" ry="26" fill="#fff" stroke="#111" stroke-width="2"/>'+T(160,64,cap,9))
V=[
X(1,'DIVINE QUALITIES · I',
 DQ('A serene person surrounded by divine qualities',['FEARLESSNESS','PURITY','STEADFASTNESS','CHARITY','SELF-CONTROL']),
 'The Lord said: Fearlessness, purity of heart, steadfastness in knowledge and yoga, charity, self-control, sacrifice, study of scripture, austerity and uprightness;',
 [('abhayam','<b>fearlessness</b>'),('sattva-saṃśuddhiḥ','<b>purity of heart</b>'),('jñāna-yoga-vyavasthitiḥ','<b>steadfastness in knowledge and yoga</b>'),('dānam damaḥ ca yajñaḥ ca','<b>charity, self-control, sacrifice</b>'),('svādhyāyaḥ tapaḥ ārjavam','<b>study, austerity, uprightness</b>')],
 'Chapter 16 begins a famous list of 26 divine qualities.',
 'Fearlessness heads the list. Commentators say it is first because fear blocks every other virtue; one who trusts in God and knows the Self has nothing to fear. These qualities return in many Hindu prayers and ethics texts.',
 'Courage, purity and honesty: begin with these and others follow.',
 'First of all: <b>fearlessness</b>.'),
X(2,'DIVINE QUALITIES · II',
 DQ('Kindness, truth, calm and gentleness listed',['AHIṂSĀ','SATYA','NO ANGER','PEACE','KINDNESS']),
 '“…non-violence, truth, freedom from anger, renunciation, peacefulness, not speaking ill of others, compassion for beings, freedom from greed, gentleness, modesty, not being fickle;”',
 [('ahiṃsā satyam akrodhaḥ','<b>non-violence, truth, no anger</b>'),('tyāgaḥ śāntiḥ apaiśunam','<b>renunciation, peace, no slander</b>'),('dayā bhūteṣu aloluptvam','<b>compassion for beings, no greed</b>'),('mārdavam hrīḥ acāpalam','<b>gentleness, modesty, steadiness</b>')],
 'More qualities: non-violence, truth, compassion, gentleness.',
 '<i>Apaiśuna</i>, not back-biting, is a striking inclusion. <i>Hrī</i>, a healthy sense of shame before doing wrong. Commentators: these are everyday ethics, not only for monks.',
 'Don’t speak ill of others. That one practice changes relationships.',
 'Truth, compassion, <b>gentleness</b>.'),
X(3,'DIVINE QUALITIES · III',
 DQ('Vigour, forgiveness, fortitude, purity, humility',['TEJAS','FORGIVENESS','FORTITUDE','NO HATRED','NO PRIDE']),
 '“…vigour, forgiveness, fortitude, purity, freedom from malice and from excessive pride: these belong to one born with the divine endowment, Bhārata.”',
 [('tejaḥ kṣamā dhṛtiḥ śaucam','<b>vigour, forgiveness, fortitude, purity</b>'),('adrohaḥ na atimānitā','<b>no malice, no excessive pride</b>'),('bhavanti sampadam daivīm','<b>these belong to the divine endowment</b>'),('abhijātasya bhārata','<b>of one born to it</b>')],
 'The list of 26 ends with forgiveness and humility.',
 'Note <i>tejas</i>, vigour, sits beside <i>kṣamā</i>, forgiveness: the divine nature is strong and gentle at once. Commentators call these qualities a “wealth” (sampat): the true treasure.',
 'Strength and forgiveness belong together.',
 'Strong, forgiving, <b>humble</b>.'),
X(4,'DEMONIC QUALITIES',
 AQ('A swaggering figure full of pride and anger','PRIDE · ANGER'),
 '“Hypocrisy, arrogance, excessive pride, anger, harshness and ignorance: these belong to one born with the demonic endowment, Pārtha.”',
 [('dambhaḥ darpaḥ abhimānaḥ ca','<b>hypocrisy, arrogance, pride</b>'),('krodhaḥ pāruṣyam eva ca','<b>anger and harshness</b>'),('ajñānam ca abhijātasya','<b>and ignorance, of one born</b>'),('pārtha sampadam āsurīm','<b>to the demonic endowment</b>')],
 'Six demonic qualities, the opposite of the divine list.',
 'The “demonic” (<i>āsurī</i>) is a nature, not a species. Commentators: anyone can show these traits; anyone can change. Hypocrisy comes first, as fearlessness did for the divine.',
 'Watch for hypocrisy and harshness in yourself first, before seeing it in others.',
 'Pride, anger, <b>harshness</b>.'),
X(5,'YOU ARE BORN WITH THE DIVINE',
 S('Krishna reassuring Arjuna that he has divine qualities','KA','light','MĀ ŚUCAḤ'),
 '“The divine endowment leads to liberation, the demonic to bondage. Do not grieve, Pāṇḍava: you are born with the divine endowment.”',
 [('daivī sampat vimokṣāya','<b>the divine endowment, for liberation</b>'),('nibandhāya āsurī matā','<b>the demonic, for bondage</b>'),('mā śucaḥ','<b>do not grieve</b>'),('sampadam daivīm abhijātaḥ asi pāṇḍava','<b>you are born to the divine endowment</b>')],
 'Kṛṣṇa reassures Arjuna.',
 'A tender moment: Arjuna, hearing the list, may worry about himself. Kṛṣṇa says “do not grieve” (mā śucaḥ, also in 18.66). Commentators: the very worry is a sign of the divine nature.',
 'If you worry about being good, you probably already are on the right path.',
 '<b>Do not grieve</b>: you are divine-born.'),
X(6,'TWO KINDS OF BEINGS',
 S('Two groups of people: divine and demonic','K','family','DAIVA · ĀSURA'),
 '“There are two kinds of beings in this world, Pārtha: the divine and the demonic. The divine has been described at length; now hear from me of the demonic.”',
 [('dvau bhūta-sargau loke asmin','<b>two kinds of beings in this world</b>'),('daivaḥ āsuraḥ eva ca','<b>the divine and the demonic</b>'),('daivaḥ vistaraśaḥ proktaḥ','<b>the divine described at length</b>'),('āsuram pārtha me śṛṇu','<b>hear of the demonic from me</b>')],
 'Kṛṣṇa now describes the demonic nature in detail.',
 'Why describe it at length? Commentators: to recognise it and avoid it, in ourselves above all.',
 'Knowing the shape of a trap helps you avoid it.',
 'Divine and <b>demonic natures</b>.'),
X(7,'NO TRUTH, NO PURITY',
 AQ('A figure confused about right and wrong','NO DIRECTION'),
 '“Demonic people do not know what to do and what to refrain from. Neither purity, nor right conduct, nor truth is found in them.”',
 [('pravṛttim ca nivṛttim ca','<b>what to do and what not to do</b>'),('janāḥ na viduḥ āsurāḥ','<b>demonic people do not know</b>'),('na śaucam na api ca ācāraḥ','<b>neither purity nor conduct</b>'),('na satyam teṣu vidyate','<b>nor truth is found in them</b>')],
 'The demonic lack a moral compass.',
 '<i>Pravṛtti</i> and <i>nivṛtti</i>: action and restraint. Commentators: the demonic nature cannot tell when to act and when to hold back.',
 'Knowing when to say no is as important as knowing when to say yes.',
 'No compass, <b>no truth</b>.'),
X(8,'“THE WORLD HAS NO GOD”',
 AQ('A figure declaring the world is random, without God','NO GOD, ONLY DESIRE'),
 '“They say the world is unreal, without foundation, without a God; born of mutual union, with desire as its only cause. What else?”',
 [('asatyam apratiṣṭham te','<b>unreal, without foundation, they say</b>'),('jagat āhuḥ anīśvaram','<b>the world is without a Lord</b>'),('aparaspara-sambhūtam','<b>born of union of male and female</b>'),('kim anyat kāma-haitukam','<b>caused by desire, what else?</b>')],
 'The demonic worldview: no meaning, no God, only desire.',
 'Commentators link this to materialist schools of the time (Lokāyata). The Gītā’s concern is ethical: a worldview with desire as the only purpose leads to cruelty.',
 'What we believe about the world shapes how we treat it.',
 '“Desire is all <b>there is</b>.”'),
X(9,'ENEMIES OF THE WORLD',
 AQ('Small-minded figures doing harm, destroying the world','HARM'),
 '“Holding this view, these lost souls of small understanding and cruel deeds rise up as enemies of the world, for its destruction.”',
 [('etām dṛṣṭim avaṣṭabhya','<b>holding this view</b>'),('naṣṭa-ātmānaḥ alpa-buddhayaḥ','<b>lost souls, of small understanding</b>'),('prabhavanti ugra-karmāṇaḥ','<b>those of cruel deeds arise</b>'),('kṣayāya jagataḥ ahitāḥ','<b>as enemies, for the world’s destruction</b>')],
 'Wrong views lead to harmful acts.',
 'Commentators: <i>alpa-buddhi</i>, small understanding, sees only the self and its pleasures, and so harms the world.',
 'A narrow view of life can do great harm. Widen your view.',
 'Small minds, <b>cruel deeds</b>.'),
X(10,'INSATIABLE DESIRE',
 AQ('A figure grasping endlessly, never satisfied','NEVER ENOUGH'),
 '“Clinging to insatiable desire, full of hypocrisy, pride and arrogance, holding wrong views through delusion, they act with impure resolves.”',
 [('kāmam āśritya duṣpūram','<b>clinging to insatiable desire</b>'),('dambha-māna-mada-anvitāḥ','<b>full of hypocrisy, pride, arrogance</b>'),('mohāt gṛhītvā asat-grāhān','<b>taking wrong views through delusion</b>'),('pravartante aśuci-vratāḥ','<b>they act with impure vows</b>')],
 'Desire that cannot be filled drives them.',
 '<i>Duṣpūra</i>, insatiable: compare 3.39. Commentators: the demonic nature is not about having desires but being ruled by endless ones.',
 'Notice when “enough” never comes. That is the warning sign.',
 'Desire <b>never satisfied</b>.'),
X(11,'ENDLESS ANXIETY',
 AQ('A worried figure chasing pleasure till death','ONLY PLEASURE'),
 '“Beset by countless anxieties that end only with death, holding the enjoyment of desires as the highest aim, convinced that this is all,”',
 [('cintām aparimeyām ca','<b>countless anxieties</b>'),('pralaya-antām upāśritāḥ','<b>lasting until death</b>'),('kāma-upabhoga-paramāḥ','<b>holding enjoyment as highest</b>'),('etāvat iti niścitāḥ','<b>sure that this is all</b>')],
 'A life of pleasure-seeking is also a life of worry.',
 'Commentators note the pairing: endless enjoyment and endless anxiety. The two go together.',
 'Chasing pleasure brings worry along. Contentment brings peace.',
 'Endless pleasure, <b>endless worry</b>.'),
X(12,'HUNDREDS OF HOPES',
 AQ('A figure tied by many ropes of hope, piling up wealth','GREED'),
 '“Bound by hundreds of ropes of hope, given over to desire and anger, they seek to amass wealth by unjust means for the enjoyment of desires.”',
 [('āśā-pāśa-śataiḥ baddhāḥ','<b>bound by hundreds of ropes of hope</b>'),('kāma-krodha-parāyaṇāḥ','<b>devoted to desire and anger</b>'),('īhante kāma-bhoga-artham','<b>strive for enjoyment of desires</b>'),('anyāyena artha-sañcayān','<b>to amass wealth unjustly</b>')],
 'Ropes of hope bind them; they gather wealth unjustly.',
 'Note: wealth itself is not condemned; <i>anyāya</i>, unjust means, is. Commentators: hope here is greedy expectation.',
 'Earn honestly. Unjust wealth binds the one who gathers it.',
 'Bound by <b>a hundred hopes</b>.'),
X(13,'“THIS IS MINE”',
 AQ('A figure counting wealth and saying mine','MINE! MORE!'),
 '“‘This I have gained today; this desire I shall fulfil. This is mine, and this wealth too will be mine.’”',
 [('idam adya mayā labdham','<b>this I have gained today</b>'),('imam prāpsye manoratham','<b>this wish I will fulfil</b>'),('idam asti idam api me','<b>this is mine, this too</b>'),('bhaviṣyati punaḥ dhanam','<b>wealth will be mine again</b>')],
 'Kṛṣṇa voices the demonic mind’s thoughts.',
 'The verses 16.13–15 sound like a person speaking to himself. Commentators: the word “mine” (<i>me</i>) runs through them, recalling Dhṛtarāṣṭra’s “māmakāḥ” in 1.1.',
 'Listen to the “mine, more, mine” in your own head. Smile at it.',
 '<b>“Mine, and more mine.”</b>'),
X(14,'“I KILLED HIM”',
 AQ('A figure boasting over a defeated enemy','I AM THE LORD!'),
 '“‘That enemy has been slain by me, and I shall slay others too. I am the lord, I am the enjoyer, I am successful, strong and happy.’”',
 [('asau mayā hataḥ śatruḥ','<b>that enemy was slain by me</b>'),('haniṣye ca aparān api','<b>and I will slay others</b>'),('īśvaraḥ aham aham bhogī','<b>I am lord, I am enjoyer</b>'),('siddhaḥ aham balavān sukhī','<b>I am successful, strong, happy</b>')],
 'The ego’s boasting.',
 'Six “I”s in two lines. Commentators see the opposite of 2.71, “without I and mine”.',
 'When “I” swells, something is wrong. Return to gratitude.',
 '<b>“I, I, I.”</b>'),
X(15,'“WHO IS EQUAL TO ME?”',
 AQ('A rich, proud figure making a show of charity','WHO IS LIKE ME?'),
 '“‘I am wealthy and high-born. Who else is equal to me? I will perform sacrifices, I will give charity, I will rejoice.’ So they speak, deluded by ignorance.”',
 [('āḍhyaḥ abhijanavān asmi','<b>I am wealthy and high-born</b>'),('kaḥ anyaḥ asti sadṛśaḥ mayā','<b>who else is like me?</b>'),('yakṣye dāsyāmi modiṣye','<b>I will sacrifice, give, rejoice</b>'),('iti ajñāna-vimohitāḥ','<b>thus, deluded by ignorance</b>')],
 'Even religious acts become ego displays.',
 'A subtle point: sacrifice and charity done for show are part of the demonic nature. Commentators connect it to 17.12 and 17.18.',
 'Good deeds done for show lose their goodness.',
 'Charity <b>for show</b>.'),
X(16,'CAUGHT IN THE NET',
 AQ('A figure trapped in a net of confused thoughts, falling','NET OF MOHA'),
 '“Bewildered by many thoughts, caught in the net of delusion, addicted to the enjoyment of desires, they fall into a foul hell.”',
 [('aneka-citta-vibhrāntāḥ','<b>bewildered by many thoughts</b>'),('moha-jāla-samāvṛtāḥ','<b>covered by the net of delusion</b>'),('prasaktāḥ kāma-bhogeṣu','<b>addicted to enjoyment of desires</b>'),('patanti narake aśucau','<b>they fall into a foul hell</b>')],
 'Confusion and addiction lead downward.',
 'Commentators read “hell” both as an after-death state and as the inner hell of a tormented mind. The net image fits: the more one struggles selfishly, the tighter it pulls.',
 'Many scattered thoughts make a net. Simplify.',
 'Caught in <b>the net of delusion</b>.'),
X(17,'SACRIFICE IN NAME ONLY',
 AQ('A showy ritual, a proud man in front','FOR SHOW'),
 '“Self-conceited, stubborn, filled with pride and the intoxication of wealth, they perform sacrifices in name only, with hypocrisy, not according to the rules.”',
 [('ātma-sambhāvitāḥ stabdhāḥ','<b>self-conceited, stubborn</b>'),('dhana-māna-mada-anvitāḥ','<b>with pride and intoxication of wealth</b>'),('yajante nāma-yajñaiḥ te','<b>they sacrifice in name only</b>'),('dambhena avidhi-pūrvakam','<b>with hypocrisy, not by rule</b>')],
 'Religion as status display.',
 'Commentators: the outer form is there, the inner spirit is missing. The Gītā repeatedly values motive over show.',
 'Rituals have meaning only with sincerity.',
 'Ritual <b>for show</b>.'),
X(18,'HATING ME IN ALL',
 AQ('A spiteful figure, unknowingly hating the Divine in others','MALICE'),
 '“Given to ego, force, pride, desire and anger, these malicious people hate me, dwelling in their own bodies and in others’.”',
 [('ahaṅkāram balam darpam','<b>ego, force, pride</b>'),('kāmam krodham ca saṃśritāḥ','<b>given to desire and anger</b>'),('mām ātma-para-deheṣu','<b>me, in their own and others’ bodies</b>'),('pradviṣantaḥ abhyasūyakāḥ','<b>hating, malicious</b>')],
 'Hating others is hating God in them.',
 'A profound point: since God dwells in every body (13.2, 15.15), hatred of anyone is hatred of the Divine, even of the Divine in oneself. Commentators link this to 13.28.',
 'When you hate someone, remember who lives in them.',
 'Hating others <b>is hating God in them</b>.'),
X(19,'AGAIN AND AGAIN',
 S('A cycle of births spiralling downward for the cruel','','wheel','AJASRAM'),
 '“Those cruel haters, the worst of people, I hurl again and again into demonic wombs in the cycles of birth.”',
 [('tān aham dviṣataḥ krūrān','<b>those cruel haters, I</b>'),('saṃsāreṣu nara-adhamān','<b>the worst of people, in the cycles</b>'),('kṣipāmi ajasram aśubhān','<b>hurl again and again, the impure</b>'),('āsurīṣu eva yoniṣu','<b>into demonic wombs</b>')],
 'A hard verse about consequences.',
 'Commentators soften the first-person voice: it is the law of karma, which the Lord administers, not personal anger. The phrase also teaches that cruelty perpetuates itself: hateful habits lead to hateful births.',
 'Cruelty breeds more cruelty, for the cruel above all. Break the cycle.',
 'Cruelty <b>repeats itself</b>.'),
X(20,'THE LOWEST STATE',
 S('A downward spiral never reaching the light','','wheel','ADHAMĀM GATIM'),
 '“Entering demonic wombs, deluded birth after birth, never reaching me, son of Kuntī, they then go to the lowest state.”',
 [('āsurīm yonim āpannāḥ','<b>entering demonic wombs</b>'),('mūḍhāḥ janmani janmani','<b>deluded, birth after birth</b>'),('mām aprāpya eva kaunteya','<b>not reaching me</b>'),('tataḥ yānti adhamām gatim','<b>then go to the lowest state</b>')],
 'Without change, the fall continues.',
 'Commentators of devotional schools stress “never reaching me”: the tragedy is missing God, not just suffering. Yet 9.30 promises that even the worst can turn.',
 'No state is permanent; even this verse leaves room, with 9.30, for return.',
 'Without change, <b>the fall continues</b>.'),
X(21,'THE THREE GATES OF HELL',
 S('Three dark gates labelled desire, anger and greed','','demon','KĀMA · KRODHA · LOBHA'),
 '“There are three gates of hell, destructive of the self: desire, anger and greed. Therefore one should give up these three.”',
 [('tri-vidham narakasya idam','<b>threefold is this gate</b>'),('dvāram nāśanam ātmanaḥ','<b>of hell, ruining the self</b>'),('kāmaḥ krodhaḥ tathā lobhaḥ','<b>desire, anger and greed</b>'),('tasmāt etat trayam tyajet','<b>therefore give up these three</b>')],
 'A famous summary: desire, anger, greed are the gates of hell.',
 'Commentators: all three are linked. Desire, blocked, becomes anger (2.62); satisfied, it becomes greed. Close one gate and the others weaken.',
 'Watch for these three in yourself daily. Closing them is closing the door to misery.',
 'Three gates: <b>desire, anger, greed</b>.'),
X(22,'FREED FROM THE THREE',
 S('A person walking away from three dark gates into light','Y','light','PARĀM GATIM'),
 '“A person freed from these three gates of darkness, son of Kuntī, does what is good for the self, and so reaches the supreme goal.”',
 [('etaiḥ vimuktaḥ kaunteya','<b>freed from these</b>'),('tamaḥ-dvāraiḥ tribhiḥ naraḥ','<b>three gates of darkness, a person</b>'),('ācarati ātmanaḥ śreyaḥ','<b>does what is good for the self</b>'),('tataḥ yāti parām gatim','<b>then reaches the supreme goal</b>')],
 'Escaping the three gates opens the way up.',
 'Commentators: freedom from these three is not the end but the beginning; then one naturally does what is truly good.',
 'Every time you let go of anger or greed, you step toward the light.',
 'Free of the three, <b>rise</b>.'),
X(23,'IGNORING SCRIPTURE',
 S('A person throwing away a guidebook and following whim','P','book','KĀMA-KĀRATAḤ'),
 '“One who sets aside the injunctions of scripture and acts on the impulse of desire attains neither perfection, nor happiness, nor the supreme goal.”',
 [('yaḥ śāstra-vidhim utsṛjya','<b>who, setting aside scripture’s rule</b>'),('vartate kāma-kārataḥ','<b>acts on desire’s impulse</b>'),('na saḥ siddhim avāpnoti','<b>he does not attain perfection</b>'),('na sukham na parām gatim','<b>nor happiness, nor the supreme goal</b>')],
 'Acting only on desire fails.',
 'The contrast is between guided action and impulsive action. Commentators: scripture here means accumulated wisdom, a guide beyond one’s own wants.',
 'Impulse is a poor guide. Lean on proven wisdom.',
 'Impulse <b>leads nowhere</b>.'),
X(24,'LET SCRIPTURE GUIDE YOU',
 S('Arjuna consulting a book of wisdom before acting','A','book','PRAMĀṆAM'),
 '“Therefore let scripture be your authority in deciding what should be done and what should not be done. Knowing what scripture prescribes, you should act here.”',
 [('tasmāt śāstram pramāṇam te','<b>so scripture is your authority</b>'),('kārya-akārya-vyavasthitau','<b>in deciding what to do and not do</b>'),('jñātvā śāstra-vidhāna-uktam','<b>knowing what scripture prescribes</b>'),('karma kartum iha arhasi','<b>you should act here</b>')],
 'The chapter ends: take scripture as your guide.',
 '<i>Pramāṇa</i>, a valid means of knowledge. Commentators note this does not mean blind rule-following; the Gītā itself reasons and questions. It means a trusted standard beyond personal desire. Chapter 17 explores what happens when people act with faith but outside scripture.',
 'Have a standard you trust more than your moods.',
 'Let wisdom <b>be your guide</b>.'),
]
cover=('<svg width="380" height="268" viewBox="0 0 380 268" role="img" aria-label="A path splitting in two: one bright path lined with virtues rising to light, and three dark gates of desire, anger and greed leading down">'
 '<rect width="380" height="268" fill="#0b2a4a" rx="8"/>'+GLOW(290,60,70,'#ffd60a',.35)+'<path d="M190 260 Q240 160 290 70" fill="none" stroke="#ffd60a" stroke-width="12"/>'+''.join(f'<rect x="{30+k*46}" y="150" width="34" height="60" rx="16" fill="#3a1414" stroke="#111" stroke-width="2"/>' for k in range(3))+T(47,230,'KĀMA',10,'#fff')+T(93,230,'KRODHA',10,'#fff')+T(139,230,'LOBHA',10,'#fff')+YOGI(260,130,1)+'</svg>')
P=dict(ch=16,nv=24,V=V,per=[12,12],out='/home/claude/work/gita/Gita_Chapter16.html',
 title='Divine and Demonic · Bhagavad Gītā Chapter 16 · srini.presents',
 desc='Bhagavad Gītā chapter 16, Daivāsura Sampad Vibhāga Yoga, every śloka explained: the 26 divine qualities beginning with fearlessness, the demonic nature of pride, anger and endless desire, the three gates of hell (desire, anger, greed), and scripture as a guide. All 24 ślokas in IAST, each on two pages.',
 burst='CHAPTER 16 OF 18',h1='DIVINE AND DEMONIC',series='BHAGAVAD GĪTĀ · CHAPTER 16 · DAIVĀSURA SAMPAD VIBHĀGA YOGA',tag='Two natures, three gates · every śloka explained',cover=cover,
 where=[f'In {chl(15)} Kṛṣṇa revealed himself as Puruṣottama, the Supreme Person.',
  'Chapter 16 is about character. Kṛṣṇa lists 26 divine qualities, from fearlessness and truth to forgiveness and humility, and then describes the demonic nature from the inside: “this is mine, I killed him, who is equal to me?” He names the three gates of hell, desire, anger and greed, and tells Arjuna: you are born with the divine.'],
 wtalk=("Are some people demons?","The Gītā speaks of natures, not species. Both lists are mirrors. Look for yourself in each."),
 fullnote=FULLNOTE,
 secs=[('THE DIVINE NATURE',1),('TWO NATURES',4),('THE DEMONIC MIND',7),('THE THREE GATES',21)],
 end=['<b>Divine qualities (16.1–3).</b> Fearlessness, purity, charity, non-violence, truth, compassion, gentleness, forgiveness, humility.',
  '<b>Two natures (16.4–6).</b> Hypocrisy, pride, anger, harshness are demonic; the divine frees, the demonic binds. Arjuna is divine-born.',
  '<b>The demonic mind (16.7–18).</b> No God, only desire; hundreds of hopes; “mine, I killed him, who is like me?”; charity for show; hating God in others.',
  '<b>Consequences (16.19–20).</b> Cruelty repeats itself, birth after birth.',
  '<b>The way out (16.21–24).</b> Shut the three gates of desire, anger and greed; let scripture be your guide.'],
 endsub='Chapter 16 in five lines',
 next=("What's next?",f'{chl(17)}: Three kinds of faith. Faith, food, sacrifice, austerity and giving, each in sāttvika, rājasika and tāmasika forms, and the meaning of “oṃ tat sat”.'),
 endkey='<b>grow the divine qualities; shut the three gates</b>.',
 foot=FOOT(16,'Readings of “demonic” as a nature rather than a fixed class follow the mainstream commentaries. '))
build2(P)
